CREATE TYPE "ShiftStatus" AS ENUM ('DRAFT', 'OPEN', 'CLOSING', 'RECONCILIATION_REQUIRED', 'RECONCILED', 'LOCKED');
CREATE TABLE "shifts" ("id" TEXT NOT NULL, "station_id" TEXT NOT NULL, "configuration_id" TEXT NOT NULL, "shift_number" INTEGER NOT NULL, "manager_id" TEXT NOT NULL, "status" "ShiftStatus" NOT NULL DEFAULT 'DRAFT', "opening_cash" DECIMAL(12,2) NOT NULL, "closing_cash" DECIMAL(12,2), "opened_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "closed_at" TIMESTAMP(3), "notes" TEXT, CONSTRAINT "shifts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "shift_users" ("shift_id" TEXT NOT NULL, "user_id" TEXT NOT NULL, CONSTRAINT "shift_users_pkey" PRIMARY KEY ("shift_id","user_id"));
CREATE TABLE "shift_tank_readings" ("id" TEXT NOT NULL, "shift_id" TEXT NOT NULL, "tank_id" TEXT NOT NULL, "opening_dip" DECIMAL(12,3) NOT NULL, "closing_dip" DECIMAL(12,3), CONSTRAINT "shift_tank_readings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "shift_nozzle_readings" ("id" TEXT NOT NULL, "shift_id" TEXT NOT NULL, "nozzle_id" TEXT NOT NULL, "opening_meter" DECIMAL(14,3) NOT NULL, "closing_meter" DECIMAL(14,3), CONSTRAINT "shift_nozzle_readings_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "shifts_station_id_shift_number_key" ON "shifts"("station_id","shift_number"); CREATE INDEX "shifts_station_id_status_idx" ON "shifts"("station_id","status"); CREATE UNIQUE INDEX "shift_tank_readings_shift_id_tank_id_key" ON "shift_tank_readings"("shift_id","tank_id"); CREATE UNIQUE INDEX "shift_nozzle_readings_shift_id_nozzle_id_key" ON "shift_nozzle_readings"("shift_id","nozzle_id");
ALTER TABLE "shifts" ADD CONSTRAINT "shifts_station_id_fkey" FOREIGN KEY ("station_id") REFERENCES "stations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shifts" ADD CONSTRAINT "shifts_configuration_id_fkey" FOREIGN KEY ("configuration_id") REFERENCES "station_configurations"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shifts" ADD CONSTRAINT "shifts_manager_id_fkey" FOREIGN KEY ("manager_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shift_users" ADD CONSTRAINT "shift_users_shift_id_fkey" FOREIGN KEY ("shift_id") REFERENCES "shifts"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shift_users" ADD CONSTRAINT "shift_users_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shift_tank_readings" ADD CONSTRAINT "shift_tank_readings_shift_id_fkey" FOREIGN KEY ("shift_id") REFERENCES "shifts"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shift_tank_readings" ADD CONSTRAINT "shift_tank_readings_tank_id_fkey" FOREIGN KEY ("tank_id") REFERENCES "tanks"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shift_nozzle_readings" ADD CONSTRAINT "shift_nozzle_readings_shift_id_fkey" FOREIGN KEY ("shift_id") REFERENCES "shifts"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "shift_nozzle_readings" ADD CONSTRAINT "shift_nozzle_readings_nozzle_id_fkey" FOREIGN KEY ("nozzle_id") REFERENCES "nozzles"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
